    "home.role": "Ingeniero de plataformas · infraestructura de IA",
    "home.tagline": "Ingeniero de plataforma. Diez años en Linux, seguridad y la infraestructura que mantiene a los agentes de IA honestos en producción.",
    "home.scroll": "desplazarse",
    "readout.location.label": "ubicación",
